def read_keystore_from_resources(file_name: str, password: str):

    file_path = os.path.join(os.path.dirname(__file__), file_name)
    if not os.path.exists(file_path):
        raise EdcException(f"Resource not found: {file_name}")

    try:
        with open(file_path, "rb") as f:
            data = f.read()

        pkcs12_data = pkcs12.load_key_and_certificates(data, password.encode(), default_backend())
        return pkcs12_data
    except Exception as e:
        raise EdcException(f"Failed to load keystore: {e}")

