        self.jjrounds[state] = self.jjround

def relax(e: DirectedEdge) -> None:
    v = e.from_()
    w = e.to()
    if dist_to[w] > dist_to[v] + e.weight():
        dist_to[w] = dist_to[v] + e.weight()
        edge_to[w] = e
        if w in pq:
            pq.change(w, dist_to[w]) 
        else:
            pq.insert(w, dist_to[w])

def path_to(self, v):
    if not self.has_path_to(v):
        return None
    path = []
    e = self.edge_to[v]
    while e is not None:
        path.append(e)
        e = self.edge_to[e.from_()]
    path.reverse()  
    return path

